import { US_STATES } from "@/lib/usStatesGeometry";

/**
 * The lower 48 in outline with Florida filled lime: the "By state" tile's
 * picture on the data hub (Oct 15 2026, round 3).
 *
 * Real Census geometry, the same shapes the /perm-by-state map draws
 * (`usStatesGeometry`, generated by scripts/build_us_states_geometry.py),
 * never hand-drawn. Alaska and Hawaii are insets on that map, so they are left
 * out here: the tile is a recognisable outline, not the data map.
 *
 * Coarsened for a thumbnail: every coordinate rounded to a whole unit of the
 * 975-wide box and repeated points dropped, which roughly halves the path text
 * this server component writes into the page while the outline still reads at
 * 150px. Computed once per server process; nothing here ships to the browser
 * as script.
 */

const LEFT_OUT = new Set(["AK", "HI"]);
const HIGHLIGHT = "FL";

interface Shape {
  abbr: string;
  d: string;
}

function coarsen(d: string): { d: string; xs: number[]; ys: number[] } {
  const xs: number[] = [];
  const ys: number[] = [];
  let out = "";
  let last = "";
  // The generated paths use only M, L and Z with absolute coordinates.
  for (const m of d.matchAll(/([MLZ])([^MLZ]*)/g)) {
    const cmd = m[1];
    if (cmd === "Z") {
      out += "Z";
      last = "";
      continue;
    }
    const [rx, ry] = (m[2] ?? "").trim().split(/\s+/);
    const x = Math.round(Number(rx));
    const y = Math.round(Number(ry));
    const key = `${x} ${y}`;
    if (cmd === "L" && key === last) continue;
    out += `${cmd}${key}`;
    last = key;
    xs.push(x);
    ys.push(y);
  }
  return { d: out, xs, ys };
}

const { shapes, box } = (() => {
  const list: Shape[] = [];
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const s of US_STATES) {
    if (LEFT_OUT.has(s.abbr)) continue;
    const c = coarsen(s.d);
    list.push({ abbr: s.abbr, d: c.d });
    for (const x of c.xs) {
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
    }
    for (const y of c.ys) {
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  const pad = 4;
  return {
    shapes: list,
    box: `${minX - pad} ${minY - pad} ${maxX - minX + pad * 2} ${maxY - minY + pad * 2}`,
  };
})();

export function StatesMapMini({ className = "h-auto w-full" }: { className?: string }) {
  return (
    <svg viewBox={box} className={className} aria-hidden="true">
      {shapes.map((s) => (
        <path
          key={s.abbr}
          d={s.d}
          fill={s.abbr === HIGHLIGHT ? "var(--primary)" : "none"}
          stroke="currentColor"
          strokeWidth={s.abbr === HIGHLIGHT ? 1.5 : 1}
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
          opacity={s.abbr === HIGHLIGHT ? 1 : 0.75}
        />
      ))}
    </svg>
  );
}
